  const clean = cleanText(text);
  return {
    text: clean,
    filename,
    mime,
    sha256: textSha256(clean),
    extraction_method,
    extraction_error: extraction_error || (clean === '' && extraction_method !== 'none' ? 'EMPTY_TEXT' : null),
    char_count: clean.length,
  };
